import{_ as a,c as o,o as s,ah as t,ao as i,ap as n}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"Além da Ponte do Arco-Íris — A Aliança de Deus Com Todo Ser Vivente","description":"A Ponte do Arco-Íris é uma imagem bonita, mas o arco-íris da Bíblia é maior: uma aliança eterna que Deus fez com todo ser vivente.","frontmatter":{"title":"Além da Ponte do Arco-Íris — A Aliança de Deus Com Todo Ser Vivente","description":"A Ponte do Arco-Íris é uma imagem bonita, mas o arco-íris da Bíblia é maior: uma aliança eterna que Deus fez com todo ser vivente."},"headers":[],"relativePath":"pt/pets-in-heaven/rainbow-bridge-covenant.md","filePath":"pt/pets-in-heaven/rainbow-bridge-covenant.md"}'),r={name:"pt/pets-in-heaven/rainbow-bridge-covenant.md"};function u(l,e,m,p,d,c){return s(),o("div",null,[...e[0]||(e[0]=[t('<div class="pl-quote"><p>“Dizem que ele atravessou a Ponte do Arco-Íris. Mas isso é só uma frase bonita — ou existe esperança real?”</p><p class="pl-quote-soft">Aqui está a parte surpreendente: a Bíblia realmente tem um arco-íris, e essa aliança foi feita para os animais.</p></div><section class="pl-section"><h2>1. Aquele arco-íris foi uma aliança com os animais</h2><p>Depois do dilúvio, Deus fez uma aliança com Noé, prometendo nunca mais destruir a terra com água. Mas as partes dessa aliança não eram apenas Noé e seus descendentes:</p><blockquote><p><strong>Gênesis 9:9-13</strong></p><p>&quot;And I, behold, I establish my covenant with you, and with your seed after you; And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you… And the bow shall be in the cloud; and it shall be for a token of a covenant between me and the earth.&quot;</p></blockquote><p>Observe a expressão “<em>todo ser vivente</em>” — aves, gado e todos os animais da terra são nomeados como parceiros da aliança. E Deus colocou o arco-íris nas nuvens como sinal <strong>entre Ele e a terra, com todo ser vivente</strong>.</p><p>Este é um dos fatos mais ignorados e mais ternos de toda a Escritura: <strong>Deus uma vez fez, formal e permanentemente, uma aliança com os animais.</strong></p><p>Então o nome humano “Ponte do Arco-Íris” não está tão longe assim. A Escritura diz que aquela luz é um sinal — e um sinal nunca significa “o fim”. Significa “ainda há mais”.</p></section><section class="pl-section"><h2>2. No mundo vindouro, eles se deitam em paz</h2><p>Quando Isaías descreve o mundo que Deus vai fazer, os animais são centrais na cena:</p><blockquote><p><strong>Isaías 65:25</strong></p><p>&quot;The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock… They shall not hurt nor destroy in all my holy mountain, saith the LORD.&quot;</p></blockquote><p>E o Apocalipse nos deixa ouvir quem canta na adoração final:</p><blockquote><p><strong>Apocalipse 5:13</strong></p><p>&quot;And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.&quot;</p></blockquote><p>“Toda criatura” está adorando. Não apenas as pessoas.</p><p>E os Salmos resumem tudo em uma linha curta:</p><blockquote><p><strong>Salmos 150:6</strong></p><p>&quot;Let every thing that hath breath praise the LORD.&quot;</p></blockquote><p>Todo ser que respira — inclusive ele — está dentro desse cântico.</p></section><section class="pl-section"><h2>3. Então, além da ponte, há uma promessa</h2><p>Não podemos acrescentar promessas em nome de Deus. Mas podemos permanecer dentro do que Ele já disse: Ele fez aliança com todo ser vivente; o mundo que Ele vai fazer tem animais vivendo em paz; Sua adoração final inclui “toda criatura”; tudo o que respira vai louvá-Lo.</p><p>Esses versículos não dizem “seu pet certamente está lá”. Mas tornam esta oração completamente legítima: “Senhor, que ele esteja dentro da Tua promessa.” E este é o Deus que deixou um arco-íris para os animais.</p><p class="pl-quote-soft">Considere: se Deus deixou um arco-íris para os animais, não vai se lembrar do seu?</p></section><div class="pl-quote"><p>“Tu puseste o Teu arco nas nuvens como sinal com todo ser vivente.<br>Quando eu vir aquela luz, vou me lembrar dele.<br>Que ele esteja em paz dentro da Tua promessa, assim como prometeste.<br>E que a Tua aliança me sustente nos dias em que sinto falta. Amém.”</p></div><section class="pl-section"><h2>Um pequeno ritual para você</h2><p>Se aparecer um arco-íris depois da chuva, que seja o seu sinal. Fique ali alguns segundos e fale com ele — sem precisar de conclusões, sem precisar terminar o pensamento. Na Escritura, aquela luz sempre foi “o sinal de uma aliança”, e um sinal significa que Deus não esqueceu.</p><p><a href="/pt/pets-in-heaven/">← Voltar para Pets in Heaven</a> ｜ Próximo: <a href="/pt/pets-in-heaven/permission-to-grieve">Permissão Para Sofrer</a></p></section><div class="pl-cta"><h2>Guarde os lugares que vocês viram juntos.</h2><p>Transforme as fotos dele em um cartão memorial, um pôster ou um pequeno filme — para que os dias que caminharam juntos tenham uma forma que dura.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Baixar na App Store</a></div><div class="pl-bible"><h3>Deixe a Palavra de Deus continuar com você</h3><p>Todos os versículos deste artigo vêm da Bíblia. Com o Rainbow Bible, você pode ler as Escrituras a qualquer momento e criar um widget de versículo diário — uma pequena luz nos dias em que sente saudade.</p><div class="pl-bible-shots"><figure><img src="'+i+'" alt="Widget do Rainbow Bible exibindo 2 Timóteo 2:13" loading="lazy"><figcaption>Versículo diário na tela inicial</figcaption></figure><figure><img src="'+n+'" alt="App Rainbow Bible — tema Pets no Céu exibindo Mateus 10:29-31" loading="lazy"><figcaption>Leia a Palavra no tema Pets no Céu</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Baixar o Rainbow Bible na App Store</a></div>',8)])])}const f=a(r,[["render",u]]);export{v as __pageData,f as default};
